const requestedTheme=new URLSearchParams(window.location.search).get('theme');if(requestedTheme==='light'||requestedTheme==='dark')document.documentElement.dataset.theme=requestedTheme;
const tasks=[
{id:'orientation',title:'Baseline orientation',prompt:'Find one recorded value, one unknown value and one excluded source. Explain the computed budget without treating unknown as zero.',view:'picture'},
{id:'capture',title:'Captured holding',prompt:'Review Arya\'s personal-loan capture. Work out whether it is saved, then add it only if the details are correct.',view:'holdings'},
{id:'recategorise',title:'Recategorise safely',prompt:'Change the equity fund to a debt fund. Inspect what would be removed, cancel once, then confirm once.',view:'holdings'},
{id:'cadence',title:'Budget cadence',prompt:'Find why freelance income is excluded. Correct it and predict which budget rows change.',view:'budget'},
{id:'funding',title:'Goal funding',prompt:'A ₹2,00,000 holding is earmarked ₹1,50,000 for education and ₹1,00,000 for a home deposit. Apply the links, explain each goal\'s progress, and explain what the links do not do.',view:'goals'},
{id:'outage',title:'Partial outage',prompt:'Goals are temporarily unavailable while the rest of the baseline works. Recover without creating a duplicate goal.',view:'goals'},
{id:'sideeffect',title:'Saved record, reminder failed',prompt:'Complete the holding save. Decide whether the record exists after reminder scheduling fails and what can safely be retried.',view:'holdings'},
{id:'switch',title:'Account switch',prompt:'Switch from Mira to Kabir during a pending load. Verify that no Mira record or draft appears in Kabir\'s account.',view:'picture'}
];
const state={task:tasks[0],view:'picture',account:'Mira',capturedSaved:false,recategorised:false,cadenceFixed:false,fundingLinked:false,outage:true,sideEffectSaved:false,switching:false};
const select=document.querySelector('#task-select'),title=document.querySelector('#task-title'),prompt=document.querySelector('#task-prompt'),content=document.querySelector('#content'),status=document.querySelector('#status-strip'),accountName=document.querySelector('#account-name'),dialog=document.querySelector('#dialog'),dialogBody=document.querySelector('#dialog-body');
for(const task of tasks){const option=document.createElement('option');option.value=task.id;option.textContent=task.title;select.append(option)}
function reset(id){state.task=tasks.find(t=>t.id===id)||tasks[0];state.view=state.task.view;state.account='Mira';state.capturedSaved=false;state.recategorised=false;state.cadenceFixed=false;state.fundingLinked=false;state.outage=state.task.id==='outage';state.sideEffectSaved=false;state.switching=false;title.textContent=state.task.title;prompt.textContent=state.task.prompt;accountName.textContent="Mira's records";document.querySelectorAll('fieldset input').forEach(x=>x.checked=false);render()}
function money(v){return new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v)}
function setView(view){state.view=view;render()}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));if(state.switching){status.textContent='Changing account. Previous records and drafts are cleared.';content.innerHTML='<div class="loading" aria-label="Loading Kabir records"><div class="skeleton"></div><div class="skeleton"></div></div>';return}status.textContent=state.account==='Mira'?'3 recorded groups, 1 unknown value, 1 excluded source':'Kabir: no holdings recorded, one monthly income source';({picture:renderPicture,holdings:renderHoldings,budget:renderBudget,goals:renderGoals}[state.view])()}
function renderPicture(){if(state.account==='Kabir'){content.innerHTML='<h2 class="section-title">Kabir\'s financial picture</h2><p class="section-copy">No holdings are recorded. This is unknown, not a zero balance.</p><div class="record"><div class="record-head"><h3>Salary</h3><span class="state">recorded</span></div><div class="facts"><span>Monthly floor</span><strong class="figure">₹72,000</strong></div></div>';return}content.innerHTML=`<h2 class="section-title">Your recorded picture</h2><p class="section-copy">A working set of facts, not a completeness score.</p><div class="summary"><div class="metric"><span>Recorded</span><strong>3 groups</strong></div><div class="metric"><span>Unknown</span><strong>1 value</strong></div><div class="metric"><span>Excluded</span><strong>1 source</strong></div></div>${holdingCard('Home loan','recorded',[['Outstanding',money(3180000)],['EMI',money(38000)]])}${holdingCard('Term cover','unknown',[['Sum assured','Not stated'],['Premium',money(1100)+' monthly']])}<div class="notice"><strong>Computed budget</strong><br>Uses recorded monthly sources. Freelance income is excluded until its cadence is known.</div>`}
function holdingCard(name,stateLabel,rows){return `<article class="record"><div class="record-head"><h3>${name}</h3><span class="state ${stateLabel==='unknown'?'unknown':''}">${stateLabel}</span></div><div class="facts">${rows.map(r=>`<span>${r[0]}</span><strong class="figure">${r[1]}</strong>`).join('')}</div></article>`}
function renderHoldings(){const capture=state.task.id==='capture'||state.task.id==='sideeffect';content.innerHTML=`<h2 class="section-title">Holdings</h2><p class="section-copy">Saved records and transient proposals stay visibly different.</p>${holdingCard('HDFC Equity Opportunities','recorded',[['Type',state.recategorised?'Debt mutual fund':'Equity mutual fund'],['Current value',money(286400)]])}${capture?`<article class="record"><div class="record-head"><h3>Personal loan proposal</h3><span class="state ${state.capturedSaved||state.sideEffectSaved?'':'unknown'}">${state.capturedSaved||state.sideEffectSaved?'saved':'not saved yet'}</span></div><div class="facts"><span>Outstanding</span><strong class="figure">₹4,80,000</strong><span>Interest</span><strong class="figure">14.5%</strong><span>EMI</span><strong class="figure">₹15,800</strong></div><div class="actions"><button class="button primary" data-action="save-capture">${state.capturedSaved||state.sideEffectSaved?'Saved':'Confirm and save'}</button></div></article>`:''}<div class="actions"><button class="button" data-action="recategorise">Recategorise equity fund</button></div>${state.sideEffectSaved?'<div class="error-card"><h3>Holding saved. Reminder not scheduled.</h3><p>Your financial record exists. Retry only the reminder setup.</p><button class="button" data-action="retry-reminder">Retry reminder</button></div>':''}`}
function renderBudget(){const freelance=state.cadenceFixed?18000:0;const total=95000+freelance;const net=total-39100-24000;content.innerHTML=`<h2 class="section-title">Monthly budget</h2><p class="section-copy">Computed live, not stored as a separate budget record.</p>${holdingCard('Income','recorded',[['Salary floor','₹95,000 monthly'],['Freelance',state.cadenceFixed?'₹18,000 monthly':'₹18,000, cadence unknown']])}${!state.cadenceFixed?'<div class="error-card"><h3>Freelance income excluded</h3><p>Cadence is missing, so this source is visible but not used in monthly income.</p><button class="button" data-action="fix-cadence">Add monthly cadence</button></div>':''}<div class="summary"><div class="metric"><span>Income used</span><strong>${money(total)}</strong></div><div class="metric"><span>Outflows</span><strong>₹63,100</strong></div><div class="metric"><span>Net</span><strong>${money(net)}</strong></div></div><div class="notice">Net is arithmetic from recorded sources. It is not a spending recommendation.</div>`}
function renderGoals(){if(state.outage){content.innerHTML='<h2 class="section-title">Goals</h2><div class="error-card"><h3>Goals could not be loaded</h3><p>Your other baseline records are still available. This is not an empty goals list.</p><button class="button" data-action="retry-goals">Retry goals</button></div>';return}const linked=state.fundingLinked;content.innerHTML=`<h2 class="section-title">Goals</h2><p class="section-copy">Funding links label a plan. They do not move, lock or reserve money.</p><div class="notice"><strong>Equity fund available value: ₹2,00,000</strong><br>${linked?'Total earmarked: ₹2,50,000. Because available value is 80% of the earmarks, each earmark contributes 80%.':'This holding is not yet included in goal progress.'}</div><article class="record"><div class="record-head"><h3>Further education</h3><span class="state">recorded</span></div><div class="facts"><span>Target</span><strong class="figure">₹8,00,000</strong><span>Earmark</span><strong>₹1,50,000 from equity fund</strong><span>Applied to progress</span><strong class="figure">${linked?'₹1,20,000':'₹0'}</strong></div></article><article class="record"><div class="record-head"><h3>Home deposit</h3><span class="state">recorded</span></div><div class="facts"><span>Target</span><strong class="figure">₹10,00,000</strong><span>Earmark</span><strong>₹1,00,000 from equity fund</strong><span>Applied to progress</span><strong class="figure">${linked?'₹80,000':'₹0'}</strong></div></article><div class="actions"><button class="button primary" data-action="link-funding">${linked?'Planning links applied':'Apply both planning links'}</button></div><div class="notice">The holding is counted once across both goals. Unknown or unsupported values stay unknown rather than becoming zero.</div>`}
function openRecategorise(){dialogBody.innerHTML='<h2 id="dialog-title">Review recategorisation</h2><p>Changing this record to Debt mutual fund resets fields that do not belong to the new type.</p><div class="field-loss">Removed if saved: risk bucket, current value, invested amount<br>Kept locally until you confirm: display name</div><div class="actions"><button class="button" data-action="cancel-dialog">Cancel</button><button class="button primary" data-action="confirm-recategorise">Confirm change</button></div>';dialog.showModal()}
function handle(action){if(action==='recategorise')openRecategorise();if(action==='cancel-dialog')dialog.close();if(action==='confirm-recategorise'){state.recategorised=true;dialog.close();render()}if(action==='save-capture'){if(state.task.id==='sideeffect'){state.sideEffectSaved=true}else state.capturedSaved=true;render()}if(action==='fix-cadence'){state.cadenceFixed=true;render()}if(action==='link-funding'){state.fundingLinked=true;render()}if(action==='retry-goals'){state.outage=false;render()}if(action==='retry-reminder'){document.querySelector('.error-card').innerHTML='<h3>Reminder scheduled</h3><p>The saved holding was not created again.</p>'}}
select.addEventListener('change',e=>reset(e.target.value));document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action)handle(action)});document.querySelector('#switch-account').addEventListener('click',()=>{state.switching=true;render();setTimeout(()=>{state.account=state.account==='Mira'?'Kabir':'Mira';state.switching=false;accountName.textContent=`${state.account}'s records`;render()},500)});reset('orientation');
